import sys
import heapq

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal(n, edges, skip_edge):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    mst_weight = 0
    mst_edges = []

    for weight, u, v, idx in edges:
        if idx == skip_edge:
            continue
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_edges.append((u, v, weight))
            mst_weight += weight

    return mst_weight, mst_edges

def second_mst(n, edges, first_edge):
    original_weight, _ = kruskal(n, edges, -1)
    _, mst_edges = kruskal(n, edges, first_edge)
    first_edge_weight = edges[first_edge][0]

    min_increase = float('inf')
    for u, v, weight in mst_edges:
        if weight < first_edge_weight:
            min_increase = min(min_increase, first_edge_weight - weight)

    max_decrease = float('-inf')
    for weight, u, v, idx in edges:
        if idx != first_edge and weight > first_edge_weight:
            new_weight, _ = kruskal(n, edges, idx)
            if new_weight == original_weight:
                max_decrease = max(max_decrease, weight - first_edge_weight)

    if min_increase == float('inf'):
        min_increase = 0
    if max_decrease == float('-inf'):
        max_decrease = 0

    return first_edge_weight + min_increase - max_decrease

